          'CİHAZ DÖKÜMÜ / ZİMMET: müşteri detayı → “🖨️ Döküm”. Kat/oda gruplu tüm cihazlar + imza alanı. “Sayaç sütunu boş” seçeneği saha föyü olur.',
          'Fatura ve tahsilat makbuzu: ilgili kayıtta “Yazdır”.',
